 --popover: color-mix(in srgb, var(--royal-color-paper) 92%, transparent); --popover-foreground: var(--royal-color-ink);
 --primary: var(--royal-color-accent); --primary-foreground: var(--royal-color-on-accent);
 --secondary: var(--royal-color-wash); --secondary-foreground: var(--royal-color-ink);
 --muted: var(--royal-color-wash); --muted-foreground: var(--royal-color-muted);
 --accent: var(--royal-color-wash); --accent-foreground: var(--royal-color-accent-text);
 --destructive: var(--royal-color-error); --border: var(--royal-color-rule); --input: var(--royal-color-rule); --ring: var(--royal-color-focus);
 --chart-1: var(--royal-color-series-1); --chart-2: var(--royal-color-series-2); --chart-3: var(--royal-color-series-3); --chart-4: var(--royal-color-series-4); --chart-5: var(--royal-color-series-5);
 --sidebar: var(--royal-color-wash); --sidebar-foreground: var(--royal-color-ink); --sidebar-primary: var(--royal-color-accent); --sidebar-primary-foreground: var(--royal-color-on-accent); --sidebar-accent: var(--royal-color-paper); --sidebar-accent-foreground: var(--royal-color-accent-text); --sidebar-border: var(--royal-color-rule); --sidebar-ring: var(--royal-color-focus);
 --radius: var(--royal-radius-control);      }
/* Tailwind's ease-out utility takes Royal's curve. */
:root { --ease-out: var(--royal-ease-out); }
:root { color-scheme: light; }
/* Dark: floating surfaces sit one step above the page. */
.dark { color-scheme: dark; --popover: color-mix(in srgb, var(--royal-color-raised) 92%, transparent); }

/* Component rules sit in Tailwind's utilities layer, after its own utilities, so a rule wins over a
 * component's utility class only when its selector is stronger, or as strong. */
@layer utilities {
/* Buttons. The Button component adds royal-button to its filled and outlined
 * variants and royal-primary to the default one. Reflective is the finish
 * unless an ancestor sets data-finish, which the specimen page uses to switch
 * it. The base rule has no specificity, so any utility class on a Button wins
 * over it, as it would over a rule loaded before Tailwind's utilities. */
