@media (hover: hover) and (pointer: fine) {
  .royal-button:not(:disabled):hover { border-color: color-mix(in srgb, var(--royal-color-accent) 60%, var(--royal-color-paper)); background-color: var(--royal-color-wash); }
  .royal-button:is(.royal-primary,[aria-pressed='true'],[aria-current='page']):not(:disabled):hover { background-color: var(--royal-color-accent-hover); border-color: var(--royal-color-accent-hover); }
  .royal-button:where(:not([data-finish] *)):is(.royal-primary,[aria-pressed='true'],[aria-current='page']):not(:disabled):hover { background-image: linear-gradient(180deg, var(--royal-color-control-sheen), var(--royal-color-glass-clear) 65%); box-shadow: var(--royal-shadow-highlight), var(--royal-shadow-control); }
}
.royal-button:active:not(:disabled) { transform: translateY(1px); }
:where(.royal-button):disabled { background: var(--royal-color-wash); background-image: none; border-color: var(--royal-color-rule); color: var(--royal-color-disabled); box-shadow: none; }
/* Base. Every border defaults to the border colour, as in shadcn. The body
 * takes Royal's text, ground and line height, so overlays rendered into
 * <body> read the same as the page. */
*, ::before, ::after { border-color: var(--border); }
body { background: var(--royal-color-paper); color: var(--royal-color-ink); font-family: var(--royal-font-body); font-size: var(--royal-text-body); line-height: 1.5; }
:is([data-slot],[data-royal-control]):focus-visible { outline: 1px solid var(--royal-color-focus); outline-offset: 2px; box-shadow: none; }
:is([data-slot='card-title'],[data-slot='dialog-title'],[data-slot='alert-dialog-title'],[data-slot='sheet-title'],[data-slot='drawer-title']) { font-family: var(--royal-font-display); font-weight: var(--royal-weight-heading); letter-spacing: var(--royal-tracking-heading); line-height: var(--royal-leading-heading); font-style: normal; }
:is([data-slot='card-title'],[data-slot='dialog-title'],[data-slot='alert-dialog-title'],[data-slot='sheet-title'],[data-slot='drawer-title']) { font-size: var(--royal-text-heading); letter-spacing: var(--royal-tracking-heading); }
/* Royal's control text, on controls that are themselves components. */
:is(button:where([data-slot]),input:where([data-slot]),textarea:where([data-slot]),select:where([data-slot]),label:where([data-slot]),[role='menuitem'],[role='menuitemcheckbox'],[role='menuitemradio'],[role='option']) { font-family: var(--royal-font-body); font-size: var(--royal-text-label); }
