:is(:is([data-slot='input'],[data-royal-control='input']),:is([data-slot='select-trigger'],[data-royal-control='select-trigger']),[data-slot='combobox-input'],[data-slot='native-select'],[data-slot='input-group']) { min-height: var(--royal-control-height); height: var(--royal-control-height); border-radius: var(--royal-radius-control); }
