:is([data-slot='popover-content'],[data-slot='select-content'],[data-slot='dropdown-menu-content'],[data-slot='dropdown-menu-sub-content'],[data-slot='context-menu-content'],[data-slot='context-menu-sub-content'],[data-slot='menubar-content'],[data-slot='menubar-sub-content'],[data-slot='hover-card-content'],[data-slot='combobox-content'],[data-slot='tooltip-content'],[data-slot='navigation-menu-viewport']) { border-radius: var(--royal-radius-control); backdrop-filter: blur(var(--royal-glass-blur)); background-color: var(--popover); box-shadow: var(--royal-shadow-edge),var(--royal-shadow-overlay); }
