:is([data-slot='button'],[data-royal-control='button'])[data-size='sm'] { height: 30px; min-height: 30px; padding: 4px 10px; }
:is([data-slot='button'],[data-royal-control='button'])[data-size='xs'] { height: 26px; min-height: 26px; padding: 2px 8px; font-size: var(--royal-text-small); }
