[data-slot='tabs-trigger'][data-state='active'] { color: var(--royal-color-accent-text); }
[data-slot='skeleton'] { background: var(--muted); }
:is([data-slot='badge'],[data-slot='toggle']) { border-radius: var(--royal-radius-control); }
[data-slot='code-block-content'] { font-family: var(--royal-font-code); font-size: var(--royal-text-label); }
[data-slot='sidebar-wrapper'] { min-height: 420px; height: 520px; position: relative; isolation: isolate; overflow: clip; }
[data-slot='sidebar-container'] { position: absolute; }
[data-slot='sidebar-inset'] { min-width: 0; }
[data-slot='table-container'] { max-width: 100%; }
@media (max-width: 767px) { [data-slot='dialog-content'], [data-slot='alert-dialog-content'] { max-width: calc(100vw - 32px); } }
