:is(:is([data-slot="select-trigger"],[data-royal-control="select-trigger"]),[data-slot="native-select"])[data-size="sm"] { height: 30px; min-height: 30px; }
:is([data-slot='button'],[data-royal-control='button'])[aria-pressed='true'], :is([data-slot='button'],[data-royal-control='button'])[aria-pressed='true']:hover { color: var(--primary-foreground); }
